def grade(transcript: list, workspace_path: str) -> dict:
    from pathlib import Path
    import re

    KEYS = ["quote_verified", "entity_verified", "evidence_rows", "table_format"]
    workspace = Path(workspace_path)

    report_path = workspace / "commitment_evidence.md"
    if not report_path.exists():
        for alt in ['commitments.md', 'commitment_table.md', 'action_items.md']:
            if (workspace / alt).exists():
                report_path = workspace / alt
                break
    if not report_path.exists():
        return {k: 0.0 for k in KEYS}

    content = report_path.read_text()
    cl = content.lower()

    source = ""
    for fn in ['meeting_transcript.md', 'transcript.md']:
        sp = workspace / fn
        if sp.exists():
            source = sp.read_text()
            break
    src_norm = re.sub(r"\s+", " ", source.lower())

    def _quotes(text):
        qs = []
        for pat in [r'"([^"\n]{10,})"', r"'([^'\n]{10,})'", r"`([^`\n]{10,})`",
                    "[\u201c\u201d]([^\u201c\u201d\n]{10,})[\u201c\u201d]"]:
            qs += re.findall(pat, text)
        for m in re.findall(r"(?m)^\s*>\s*(.+)$", text):
            if len(m.strip()) >= 10:
                qs.append(m.strip())
        return qs

    def _verified(q):
        qn = re.sub(r"\s+", " ", q.lower().strip())
        if len(qn) < 10 or not src_norm:
            return False
        if qn in src_norm:
            return True
        return len(qn) > 30 and qn[:30] in src_norm

    # quote_verified: fraction of quoted spans that are verbatim from source
    all_quotes = _quotes(content)
    quote_verified = (sum(1.0 for q in all_quotes if _verified(q)) / len(all_quotes)
                      if all_quotes and source else 0.0)

    # table_format: did the model produce a real table?
    pipe_lines = [l for l in content.split("\n") if "|" in l and len(l.strip()) > 10
                  and not re.match(r"^[\s|:-]+$", l.strip())]
    table_format = 1.0 if len(pipe_lines) >= 3 else (0.5 if len(pipe_lines) >= 1 else 0.0)

    # evidence_rows: rows that actually carry a verified quote (padding earns nothing)
    data_rows = pipe_lines[1:] if len(pipe_lines) > 1 else []
    verified_rows = sum(1 for row in data_rows if any(_verified(q) for q in _quotes(row)))
    evidence_rows = min(1.0, verified_rows / float(5)) if 5 else 0.0

    # entity_verified: real owners present, no hallucinated names
    known = ['cormac', 'samia', 'william', 'cindy', 'brian', 'tai']
    if source:
        sl = source.lower()
        found_real = sum(1 for n in known if n in sl and n in cl)
        table_names = re.findall(r"\|\s*([A-Z][a-z]{2,})\s*\|", content)
        skip = {"owner", "entity", "speaker", "person", "responsible", "topic",
                "action", "deadline", "evidence", "total", "claim", "stance",
                "role", "area", "status", "decision", "source", "quote",
                "timeline", "timeframe", "date", "item", "agenda", "party"}
        hallucinated = sum(1 for n in set(table_names)
                           if n.lower() not in sl and n.lower() not in skip)
        entity_verified = 1.0 if found_real >= 3 and hallucinated <= 1 else (
            0.7 if found_real >= 3 else (0.4 if found_real >= 2 else 0.0))
    else:
        entity_verified = 0.0

    return {
        "quote_verified": quote_verified,
        "entity_verified": entity_verified,
        "evidence_rows": evidence_rows,
        "table_format": table_format,
    }

